class Solution {
  public int[][] colorGrid(int n, int m, int[][] sources) {
    int[][] grid = new int[n][m];
    int[] frontier = new int[n * m], next = new int[n * m];
    int fs = 0;
    for (int[] s : sources) {
      grid[s[0]][s[1]] = s[2];
      frontier[fs++] = s[0] * m + s[1];
    }
    int[][] tmp = new int[n][m];
    int[] dx = {1, -1, 0, 0}, dy = {0, 0, 1, -1};
    while (fs > 0) {
      int ns = 0;
      for (int t = 0; t < fs; t++) {
        int x = frontier[t] / m, y = frontier[t] % m;
        for (int d = 0; d < 4; d++) {
          int a = x + dx[d], b = y + dy[d];
          if (a < 0 || b < 0 || a >= n || b >= m || grid[a][b] != 0) continue;
          if (tmp[a][b] == 0) next[ns++] = a * m + b;
          tmp[a][b] = Math.max(tmp[a][b], grid[x][y]);
        }
      }
      for (int t = 0; t < ns; t++) {
        int x = next[t] / m, y = next[t] % m;
        grid[x][y] = tmp[x][y];
      }
      int[] swap = frontier;
      frontier = next;
      next = swap;
      fs = ns;
    }
    return grid;
  }
}
